<?php
declare(strict_types=1);
ini_set('session.use_strict_mode', '1');
session_name('reintegra_pesquisa_admin');session_set_cookie_params(['httponly'=>true,'secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','samesite'=>'Lax']);session_start();header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');header('X-Robots-Tag: noindex');
if(empty($_SESSION['reintegra_pesquisa_admin'])){header('Location: /admin/');exit;}
require_once dirname(__DIR__,2).'/private/catalogo.php';
$_SESSION['catalogo_csrf']??=bin2hex(random_bytes(32));$db=cat_db();$error='';$cats=cat_categories();$fields=cat_fields();
if($_SERVER['REQUEST_METHOD']==='POST')try{
 if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['catalogo_csrf'],$_POST['csrf']))throw new RuntimeException('Sessão expirada. Atualize a página.');
 $action=$_POST['action']??'';
 if($action==='category'){$slug=$_POST['slug']??'';$name=$_POST['nome']??'';if(!is_string($slug)||!is_string($name))throw new RuntimeException('Confira código e nome da categoria.');$slug=trim($slug);$name=trim($name);if(!preg_match('/^[a-z0-9-]{2,40}$/',$slug)||mb_strlen($name)<2||mb_strlen($name)>100)throw new RuntimeException('Confira código e nome da categoria.');$st=$db->prepare('INSERT INTO catalogo_categorias(slug,nome) VALUES(?,?) ON DUPLICATE KEY UPDATE nome=VALUES(nome)');$st->execute([$slug,$name]);header('Location: /admin/catalogo.php?salvo=1');exit;}
 if($action==='category_remove'){$slug=$_POST['slug']??'';if(!is_string($slug))throw new RuntimeException('Categoria inválida.');$db->beginTransaction();$st=$db->prepare('SELECT slug FROM catalogo_categorias WHERE slug=? FOR UPDATE');$st->execute([$slug]);if(!$st->fetchColumn())throw new RuntimeException('Categoria não encontrada. Atualize a página.');foreach(cat_rows(true) as $row){$r=json_decode($row['dados'],true);if($r['categoria']===$slug)throw new RuntimeException('Transfira os serviços dessa categoria antes de removê-la.');}$st=$db->prepare('DELETE FROM catalogo_categorias WHERE slug=?');$st->execute([$slug]);$db->commit();header('Location: /admin/catalogo.php?salvo=1');exit;}
 if($action!=='save')throw new RuntimeException('Ação inválida.');
 $id=cat_save_service($db,$_POST);header('Location: /admin/catalogo.php?id='.$id.'&salvo=1');exit;
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=get_class($e)===RuntimeException::class?$e->getMessage():'Não foi possível salvar. Confira os campos e tente novamente.';}
$edit=null;$version=0;$state='rascunho';$id=filter_var($_GET['id']??0,FILTER_VALIDATE_INT,['options'=>['min_range'=>0]]);if($id===false)$id=0;
if($id){$st=$db->prepare('SELECT * FROM catalogo_servicos WHERE id=?');$st->execute([$id]);$row=$st->fetch();if($row){$edit=json_decode($row['dados'],true);$edit['codigo']=$row['codigo'];$version=(int)$row['versao'];$state=$row['status_editorial'];}}
if($error&&($_POST['action']??'')==='save'){$edit=array_filter($_POST,'is_string');$id=max(0,(int)($_POST['id']??0));$state=is_string($_POST['status_editorial']??null)?$_POST['status_editorial']:'rascunho';$version=max(0,(int)($_POST['versao']??0));}
function token():void{echo '<input type="hidden" name="csrf" value="'.cat_h($_SESSION['catalogo_csrf']).'">';}
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gestão do catálogo | ReintegraFacil</title><link rel="stylesheet" href="/assets/sistema.css"><link rel="stylesheet" href="/assets/catalogo.css"><link rel="icon" type="image/svg+xml" href="/assets/identidade/favicon.svg?v=20261108-1"><link rel="stylesheet" href="/assets/identidade/marca.css?v=20261108-1">
</head><body><a class="skip" href="#conteudo">Pular para conteúdo</a><header><div class="wrap"><a class="rf-brand " href="/" aria-label="ReintegraFacil, página inicial"><img class="rf-logo" src="/assets/identidade/reintegrafacil.svg?v=20261108-1" width="340" height="88" alt="ReintegraFacil" decoding="async"></a><br><a href="/sistema/?catalogo=1">Ver catálogo público</a> · <a href="/admin/">Pesquisa e sair da conta</a></div></header><main id="conteudo" class="wrap"><h1>Gestão do catálogo</h1><?php if($error):?><p role="alert"><?=cat_h($error)?></p><?php endif;?><?php if(isset($_GET['salvo'])&&!$error):?><p role="status">Alteração salva.</p><?php endif;?>
<div class="service"><h2><?=$id?'Editar serviço':'Novo serviço'?></h2><p class="small">Rascunhos e serviços em revisão ficam fora da consulta pública. Para publicar, complete a fonte, a orientação e as datas de conferência.</p><form method="post"><?php token();?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="versao" value="<?=$version?>"><div class="admin-fields"><label>Código do serviço<input value="<?=cat_h($edit['codigo']??'Gerado automaticamente ao salvar')?>" readonly></label><?php foreach($fields as $key=>$label):?><label class="<?=in_array($key,['descricao','passos','publico','condicoes'])?'wide':''?>"><?=cat_h($label)?><?php if(in_array($key,['descricao','passos','publico','condicoes'])):?><textarea name="<?=$key?>"><?=cat_h($edit[$key]??'')?></textarea><?php elseif(in_array($key,['categoria','escopo','modalidade'])):?><select name="<?=$key?>"><?php foreach($key==='categoria'?$cats:($key==='modalidade'?cat_modalidades():['nacional'=>'Nacional','estadual'=>'Estadual','municipal'=>'Municipal']) as $k=>$v):?><option value="<?=cat_h($k)?>" <?=($edit[$key]??($key==='modalidade'?'nao_informada':''))===$k?'selected':''?>><?=cat_h($v)?></option><?php endforeach;?></select><?php else:?><input name="<?=$key?>" type="<?=str_contains($key,'revisao')||$key==='data_verificacao'?'date':($key==='url'?'url':'text')?>" value="<?=cat_h($edit[$key]??'')?>" maxlength="2000"><?php endif;?></label><?php endforeach;?><label>Responsável editorial pela revisão<input name="editor" required maxlength="100" value="<?=cat_h($_POST['editor']??'')?>"></label><label>Motivo da revisão<input name="motivo" required maxlength="500" value="<?=cat_h($_POST['motivo']??'')?>"></label></div><p><label>Situação editorial<select name="status_editorial"><?php foreach(cat_statuses() as $key=>$label):?><option value="<?=cat_h($key)?>" <?=$state===$key?'selected':''?>><?=cat_h($label)?></option><?php endforeach;?></select></label></p><button class="button">Salvar serviço e revisão</button> <a href="/admin/catalogo.php">Cadastrar outro</a></form></div>
<section><h2>Serviços cadastrados</h2><?php foreach(cat_rows(true) as $row):$r=json_decode($row['dados'],true);?><p><a href="?id=<?=(int)$row['id']?>"><?=cat_h($r['servico'])?></a> · <?=cat_h($row['codigo'])?> · <?=cat_h(cat_statuses()[$row['status_editorial']]??$row['status_editorial'])?> · Revisão <?=cat_h($r['proxima_revisao'])?></p><?php endforeach;?></section>
<section class="service"><h2>Categorias</h2><p>Use o código existente para renomear. Remova apenas categorias sem serviços.</p><form method="post"><?php token();?><input type="hidden" name="action" value="category"><label>Código <input name="slug" required pattern="[a-z0-9-]{2,40}" maxlength="40"></label> <label>Nome <input name="nome" required maxlength="100"></label> <button class="button">Salvar categoria</button></form><?php foreach($cats as $k=>$v):?><form method="post"><?php token();?><input type="hidden" name="action" value="category_remove"><input type="hidden" name="slug" value="<?=cat_h($k)?>"><p><?=cat_h($k.' — '.$v)?> <button type="submit" class="quiet">Remover categoria vazia</button></p></form><?php endforeach;?></section>
<?php if($id):$s=$db->prepare('SELECT * FROM catalogo_revisoes WHERE servico_id=? ORDER BY id DESC');$s->execute([$id]);?><section class="service"><h2>Histórico editorial</h2><?php foreach($s as $revision):?><details><summary><?=cat_h($revision['criado_em'].' — '.$revision['responsavel'].' — '.$revision['motivo'])?></summary><h3>Estado anterior</h3><pre style="white-space:pre-wrap"><?=cat_h(json_encode(json_decode($revision['anterior']??'null'),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre><h3>Estado salvo</h3><pre style="white-space:pre-wrap"><?=cat_h(json_encode(json_decode($revision['atual']),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre></details><?php endforeach;?></section><?php endif;?></main></body></html>
